import type { IconifyJSON } from '@iconify/react/offline';

/**
 * Icons - Register Icons - Collections.
 *
 * The generated Iconify collections handed to the registrar, each carrying
 * the sliced icons and aliases a site references.
 *
 * @since 0.21.0
 */
export type Icons_RegisterIcons_Collections = IconifyJSON[];

/**
 * Icons - Register Icons - Returns.
 *
 * The registrar performs registration as a side effect and returns
 * nothing to its caller.
 *
 * @since 0.21.0
 */
export type Icons_RegisterIcons_Returns = void;
